.card-0{background:linear-gradient(125deg,#351b2be8,#171726e8);border-color:#76344880}.card-0::after{background:#e934401c}.card-0 .card-icon{background:#65263255;color:#ff7888;border-color:#a2455a66}.card-0 .card-number{color:#a36675}.card-0 .card-bottom .icon{color:#fa8395}.card-0:hover{background:linear-gradient(125deg,#482233ed,#241b2eef);border-color:#d76377;box-shadow:0 12px 30px #0004,0 0 22px #dc2e440c}.card-1{animation-delay:.05s}.card-2{animation-delay:.1s}.card-3{animation-delay:.15s}.card-4{animation-delay:.2s}.card-5{animation-delay:.25s}.module-card:disabled{cursor:not-allowed;opacity:.6}.module-card:disabled:hover{transform:none}.module-card:disabled .card-icon{transform:none}
