.ai-chat-head h2{margin:0;font-size:15.5px;letter-spacing:0;color:#eef3ff;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ai-state{margin:1px 0 0;font-size:12px;color:#8fa5c4}
.ai-orb{position:relative;display:grid;place-items:center;flex:0 0 42px;width:42px;height:42px;border-radius:13px;background:linear-gradient(140deg,#2f6fd0,#1b3f7c);color:#fff;box-shadow:0 0 0 3px #3b82f626;transition:box-shadow .24s,background .24s}
.ai-orb .system-icon{width:22px;height:22px;position:relative;z-index:1}
.ai-orb i{position:absolute;inset:0;border-radius:inherit;border:2px solid #69a7ff;opacity:0;pointer-events:none}
.ai-orb[data-state=consulting]{animation:ai-pulse 1.4s ease-in-out infinite}
.ai-orb[data-state=answering] i{animation:ai-wave 1.2s ease-out infinite}
.ai-orb[data-state=answering] i+i{animation-delay:.4s}
.ai-orb[data-state=error]{background:linear-gradient(140deg,#c2434a,#7c1f27);box-shadow:0 0 0 3px #e5484d33}
.ai-orb[data-state=consulting]+div .ai-state,.ai-orb[data-state=answering]+div .ai-state{color:#9bbef5}
.ai-orb[data-state=error]+div .ai-state{color:#ff9ea2}
.ai-orb-large{flex:0 0 58px;width:58px;height:58px;border-radius:18px;box-shadow:0 0 0 5px #3b82f61f}
.ai-orb-large .system-icon{width:30px;height:30px}
@keyframes ai-pulse{0%,100%{box-shadow:0 0 0 3px #3b82f626}50%{box-shadow:0 0 0 8px #3b82f612,0 0 18px #3b82f666}}
@keyframes ai-wave{0%{opacity:.7;transform:scale(1)}100%{opacity:0;transform:scale(1.55)}}
.ai-prefs{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px 18px;padding:14px 16px;border-bottom:1px solid #223450;background:#0d1a2d;animation:system-in .22s ease-out}
.ai-prefs fieldset{display:grid;gap:8px;align-content:start;min-width:0;margin:0;padding:0;border:0}
.ai-prefs legend{padding:0;margin-bottom:8px;font-size:11px;font-weight:700;letter-spacing:.6px;text-transform:uppercase;color:#8fa5c4}
.ai-prefs>small{grid-column:1/-1}
body[data-page=dashboard] .ai-check{display:flex;align-items:center;gap:8px;margin:0;font-size:13px;font-weight:400;color:#dbe8fb}
.ai-check input{flex:0 0 auto;width:16px;height:16px;margin:0;accent-color:#4d8df0}
body[data-page=dashboard] .ai-range{display:grid;grid-template-columns:minmax(0,110px) minmax(0,1fr);align-items:center;gap:10px;margin:0;font-size:12.5px;font-weight:400;color:#b9cce6}
body[data-page=dashboard] .ai-range input{width:100%;min-height:0;height:20px;margin:0;padding:0;border:0;background:transparent;accent-color:#4d8df0}
.ai-log{flex:1;min-height:0;overflow-y:auto;display:flex;flex-direction:column;gap:10px;padding:16px;background:#0a1322;}
.ai-log:focus-visible{outline:2px solid #8bb8ff;outline-offset:-2px}
.ai-welcome{margin:auto;display:grid;justify-items:center;gap:6px;width:100%;max-width:620px;text-align:center}
.ai-welcome h3{margin:0;font-size:16.5px;color:#eef3ff}
.ai-welcome p{margin:0;font-size:13px;line-height:1.55;color:#9bb0cf}
.ai-suggest{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px;width:100%;margin-top:8px}
.ai-suggestion{padding:8px 11px;border:1px solid #2a4063;border-radius:11px;background:#101e34;color:#c4ddff;font-size:12.5px;line-height:1.35;text-align:left;transition:background .2s,border-color .2s,transform .2s}
.ai-suggestion:hover{background:#18335a;border-color:#69a7ff}
.ai-bubble{max-width:84%;padding:10px 13px;border:1px solid #263a57;border-radius:14px;font-size:13.5px;line-height:1.55;overflow-wrap:anywhere;animation:system-in .22s ease-out}
.ai-bubble.no-anim{animation:none}
.ai-bubble p{margin:0;white-space:pre-line}.ai-bubble p+p{margin-top:8px}
.ai-adi{align-self:flex-start;border-bottom-left-radius:5px;background:#122036;color:#dbe8fb}
.ai-me{align-self:flex-end;border-color:#3a6fc0;border-bottom-right-radius:5px;background:#1d4f96;color:#fff}
.ai-author{display:block;margin-bottom:2px;font-size:10.5px;font-weight:700;letter-spacing:.4px;text-transform:uppercase;color:#8fb4ee}
.ai-me .ai-author{color:#c9dcf8}
.ai-foot{display:flex;align-items:center;gap:6px;margin-top:6px}
.ai-foot time{margin-right:auto;font-size:10.5px;color:#8198ba}.ai-me .ai-foot time{margin:0 0 0 auto;color:#c9dcf8}
.ai-listen{display:inline-flex;align-items:center;gap:5px;min-height:28px;padding:3px 9px;border:1px solid #2a4063;border-radius:999px;background:transparent;color:#9bbef5;font-size:11.5px}
.ai-listen:hover{background:#18335a;border-color:#69a7ff;transform:none}
.ai-listen .system-icon{width:13px;height:13px}
.ai-listen[data-state=playing]{background:#18335a;border-color:#69a7ff;color:#fff}
.ai-stop{display:none;padding:3px 7px}.ai-listen:is([data-state=playing],[data-state=paused])+.ai-stop{display:inline-flex}
.ai-typing{display:flex;align-items:center;gap:5px;color:#9bb0cf;font-size:12.5px}
.ai-typing-text{margin-right:4px}
.ai-typing i{width:6px;height:6px;border-radius:50%;background:#69a7ff;animation:ai-dot 1.1s ease-in-out infinite}
.ai-typing i:nth-of-type(2){animation-delay:.16s}.ai-typing i:nth-of-type(3){animation-delay:.32s}
@keyframes ai-dot{0%,70%,100%{opacity:.3;transform:translateY(0)}35%{opacity:1;transform:translateY(-3px)}}
.ai-error{border-color:#6d2a30;background:#2a1418;color:#ffd6d8}.ai-error .ai-author{color:#ff9ea2}.ai-error .ai-listen{margin-top:8px}
.ai-ask{margin:0 12px 12px;border:1px solid #2a4063;border-radius:16px;background:#0d1a2e;transition:border-color .2s,box-shadow .2s}
.ai-ask:focus-within{border-color:#5b9bff;box-shadow:0 0 0 3px #3b82f626}
body[data-page=dashboard] .ai-ask textarea{display:block;width:100%;min-height:84px;max-height:220px;margin:0;padding:13px 15px 6px;border:0;border-radius:16px 16px 0 0;background:transparent;box-shadow:none;color:#eef3ff;font-size:15px;line-height:1.5;resize:none;overflow-y:hidden;}
body[data-page=dashboard] .ai-ask textarea:focus{outline:none;border:0;box-shadow:none;background:transparent}
.ai-ask textarea::placeholder{color:#7f93b1}
.ai-ask-bar{display:flex;align-items:center;gap:8px;padding:6px 8px 8px 10px}
.ai-hint{margin-right:auto;font-size:11.5px;color:#7f93b1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ai-count{font-size:11.5px;color:#f3c677;font-variant-numeric:tabular-nums;white-space:nowrap}
.ai-ask .ai-mini{flex:0 0 38px;width:38px;height:38px;border-color:#2a4063;border-radius:11px}
.ai-ask .ai-mini .system-icon,.ai-send .system-icon{width:17px;height:17px}
.ai-send{position:relative;flex:0 0 42px;width:42px;height:38px;padding:0;border-radius:11px}
.ai-send[data-busy] .system-icon{visibility:hidden}
.ai-send[data-busy]::after{content:"";position:absolute;inset:0;margin:auto;width:16px;height:16px;border:2px solid #ffffff55;border-top-color:#fff;border-radius:50%;animation:ai-spin .7s linear infinite}
@keyframes ai-spin{to{transform:rotate(360deg)}}
.ai-mic[data-state=on]{background:#3d1a1e;border-color:#e5484d;color:#ff8f93;animation:ai-mic 1.3s ease-in-out infinite}
@keyframes ai-mic{0%,100%{box-shadow:0 0 0 0 #e5484d55}50%{box-shadow:0 0 0 6px #e5484d00}}
@media(max-width:980px){.ai-shell{grid-template-columns:minmax(0,1fr);height:auto}.ai-side{display:contents}.ai-chat{order:1;height:var(--ai-h,560px)}.ai-status{order:2}.ai-history{order:3}.ai-tiles{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media(max-width:700px){.ai-suggest{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:560px){.ai-tiles{gap:6px}.ai-tile>.system-icon{display:none}.ai-tile strong{font-size:18px}.ai-tile small{font-size:10.5px}.ai-status{padding:14px 12px}.ai-prefs{grid-template-columns:1fr;max-height:45%;overflow-y:auto}.ai-bubble{max-width:94%}.ai-chat-head{padding:9px 10px;gap:8px}.ai-log{padding:12px}.ai-ask{margin:0 8px 8px}.ai-hint{display:none}.ai-ask-bar{justify-content:space-between}.ai-count{margin-left:auto}.ai-orb{flex-basis:38px;width:38px;height:38px}}
@media(max-height:560px){#adi-widget.adi-v2 .adi-panel,body[data-page=dashboard] #adi-widget.adi-v2 .adi-panel{max-height:calc(100dvh - 80px)}#adi-widget.adi-v2 .adi-panel>header{padding-top:8px;padding-bottom:8px}}
@media(max-height:620px){body[data-page=dashboard] .ai-ask textarea{min-height:58px;padding-top:10px}.ai-welcome p{display:none}}
@media(max-width:360px){.ai-suggest{grid-template-columns:1fr}.ai-tile{padding:8px 7px}}
