body:has(.ai-shell) .adi-widget{display:none}
@media(prefers-reduced-motion:reduce){.ai-orb,.ai-orb i,.ai-typing i,.ai-mic[data-state=on],.ai-bubble,.ai-more,.ai-prefs{animation:none}.ai-orb[data-state=consulting]{box-shadow:0 0 0 5px #3b82f640}.ai-typing i{opacity:.8}.ai-tile:hover{transform:none}}
