@media(max-height:760px),(max-width:560px){#view-module:has(.ai-shell,.mail-v2) .module-heading{margin-bottom:12px}#view-module:has(.ai-shell,.mail-v2) .module-heading :is(.eyebrow,#module-description){display:none}#view-module:has(.ai-shell,.mail-v2) .module-heading h1{margin:0;font-size:21px}#view-module:has(.ai-shell,.mail-v2) .system-title-icon{width:32px;height:32px;margin-right:9px}}
@media(max-width:560px){.ai-chat{scroll-margin-bottom:8px}}
