#adi-widget.adi-v2 .adi-panel{position:absolute;right:0;bottom:60px;display:flex;flex-direction:column;width:min(352px,calc(100vw - 24px));height:clamp(400px,58dvh,460px);max-height:min(70dvh,calc(100dvh - 96px));border:1px solid #2c405c;border-radius:16px;background:#0b1526;box-shadow:0 20px 54px #020714b3;overflow:hidden;animation:adi-up .2s ease-out}
