.tracking-pro .tracking-open .track-icon,.tracking-pro .tracking-item[data-tone] .track-icon{transition:color .2s,background .2s,border-color .2s,box-shadow .2s}
.tracking-pro .tracking-item.track-new{animation:es-fade .22s ease-out}
