@keyframes es-pulse{0%{transform:scale(1);box-shadow:0 0 0 0 #4d8df099}45%{transform:scale(1.04);box-shadow:0 0 0 6px #4d8df02e,0 0 16px #4d8df066}100%{transform:scale(1);box-shadow:0 0 0 10px #4d8df000}}
@media(prefers-reduced-motion:reduce){.tracking-pro .tracking-item.track-new,.tracking-pro .tracking-item.track-new .tracking-open,.tracking-pro .panel-icon.tracking-pulse{animation:none}.tracking-pro .tracking-open,.tracking-pro .tracking-open .track-icon{transition:none}}

