.tracking-counters{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px}
.tracking-counter{display:grid;gap:2px;margin:0;padding:10px 12px;border:1px solid #22344f;border-left:3px solid #52688a;border-radius:11px;background:#0c1729;color:#c5d5ee;text-align:left;min-width:0;min-height:0;width:auto;font:inherit}
button.tracking-counter{cursor:pointer;transition:border-color .18s,background .18s}
button.tracking-counter:hover,button.tracking-counter:focus-visible{background:#11203a;border-color:#42628d;outline:0}
button.tracking-counter[aria-pressed=true]{background:#132746;border-color:#69a7ff;box-shadow:0 0 0 2px #4087ef26}
.tracking-counter strong{font-size:22px;line-height:1.1;font-weight:700;color:#fff}
.tracking-counter span{font-size:11.5px;line-height:1.3;color:#9db1cf;overflow-wrap:anywhere}
.tracking-counter[data-kind=pending]{border-left-color:#92a9ca}.tracking-counter[data-kind=process]{border-left-color:#4d8df0}.tracking-counter[data-kind=waiting]{border-left-color:#f3c677}.tracking-counter[data-kind=ready]{border-left-color:#3fbf8a}.tracking-counter[data-kind=done]{border-left-color:#7b8798}
.tracking-tools{display:grid;grid-template-columns:minmax(180px,1.6fr) repeat(2,minmax(130px,1fr)) auto auto auto;gap:8px;align-items:end;margin:0}
.tracking-tools input,.tracking-tools select{margin:0;min-height:38px;height:38px;padding:7px 10px;font-size:13px}
.tracking-date{display:grid;gap:3px;margin:0;font-size:10.5px;font-weight:600;letter-spacing:.04em;text-transform:uppercase;color:#8198ba}
.tracking-date input{width:138px}
