.tracking-tools .tracking-clear[hidden]{display:none}
.tracking-cards{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
.tracking-card{display:grid;gap:10px;align-content:start;min-width:0;padding:13px 14px;border:1px solid #22344f;border-radius:13px;background:#0c1729;transition:border-color .18s,box-shadow .18s}
.tracking-card:hover{border-color:#34507d}
.tracking-card[data-priority=urgente]{border-top:2px solid #d05663}.tracking-card[data-priority=alta]{border-top:2px solid #d99a3d}
.tracking-card.track-new{animation:tracking-card-new 1.6s ease-out 1}
@keyframes tracking-card-new{0%{box-shadow:0 0 0 2px #69a7ff99,0 0 24px #4087ef59}100%{box-shadow:0 0 0 0 #69a7ff00}}
.tracking-card-head{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:10px;align-items:center}
.tracking-card-id{display:grid;gap:1px;min-width:0}
.tracking-card-id .order-code-link{justify-self:start;margin:0;padding:0;font-size:13.5px}
.tracking-client{font-size:13px;font-weight:600;color:#e5edf9;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.tracking-card-id small{font-size:11.5px;color:#8fa5c4;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.tracking-stages{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:4px}
.tracking-stages li{position:relative;padding-top:9px;font-size:10.5px;line-height:1.3;color:#6f84a3;text-align:center;overflow-wrap:anywhere}
.tracking-stages li::before{content:"";position:absolute;left:0;right:0;top:0;height:4px;border-radius:999px;background:#1a2a45}
.tracking-stages li[data-state=done]{color:#8ff0bd}.tracking-stages li[data-state=done]::before{background:#2f9d73}
.tracking-stages li[data-state=current]{color:#fff;font-weight:700}.tracking-stages li[data-state=current]::before{background:#4d8df0;box-shadow:0 0 8px #4d8df080}
.tracking-stages li[data-state=unrecorded]::before{background:repeating-linear-gradient(90deg,#3a4b68 0 5px,#0c1729 5px 9px)}
.tracking-last{display:grid;grid-template-columns:auto minmax(0,1fr);gap:10px;align-items:start;padding:9px 10px;border:1px solid #1c2c47;border-left:3px solid var(--tk,#42628d);border-radius:10px;background:#0a1424}
.tracking-last .track-icon{display:grid;place-items:center;width:30px;height:30px;border-radius:9px;background:var(--tk-soft,#17263f);color:var(--tk,#8bb8ff);flex:none}
.tracking-last .track-icon svg,.tracking-history .track-icon svg{width:15px;height:15px}
.tracking-last>div,.tracking-history li>div{display:grid;gap:2px;min-width:0}
.tracking-last strong,.tracking-history strong{font-size:13px;color:#eef3ff}
.tracking-last span,.tracking-history li>div>span{font-size:12px;line-height:1.45;color:#b9c9e2;overflow-wrap:anywhere}
.tracking-last q,.tracking-history q{font-size:12px;line-height:1.45;color:#dbe8fb;quotes:"«" "»";overflow-wrap:anywhere}
.tracking-last small,.tracking-history small{font-size:11px;color:#8198ba}
.tracking-note{margin:0;font-size:12px;color:#8fa5c4}
.tracking-facts{display:flex;flex-wrap:wrap;gap:4px 16px;margin:0}
.tracking-facts div{display:flex;gap:6px;font-size:11.5px;min-width:0}
.tracking-facts dt{color:#8198ba}.tracking-facts dd{margin:0;color:#dbe8fb;font-weight:600;overflow-wrap:anywhere}
.tracking-actions{display:flex;flex-wrap:wrap;gap:8px}
.tracking-actions button{display:inline-flex;align-items:center;gap:7px;width:auto;margin:0;min-height:34px;padding:6px 12px;font-size:12.5px}
.tracking-actions button svg{width:15px;height:15px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.tracking-history-wrap{padding-top:10px;border-top:1px solid #1c2c47}
.tracking-history-wrap[hidden]{display:none}
.tracking-history{list-style:none;margin:0;padding:0;display:grid;gap:9px;max-height:300px;overflow-y:auto;}
.tracking-history li{display:grid;grid-template-columns:auto minmax(0,1fr);gap:9px;align-items:start}
.tracking-history .track-icon{display:grid;place-items:center;width:26px;height:26px;border-radius:8px;background:var(--tk-soft,#17263f);color:var(--tk,#8bb8ff)}
.tracking-empty{grid-column:1/-1;padding:18px;border:1px dashed #2a3d5c;border-radius:12px;text-align:center;font-size:13px;color:#9db1cf}
.tracking-foot{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:8px}
.tracking-count{margin:0;font-size:12px;color:#8fa5c4}
.tracking-pages{display:flex;align-items:center;gap:8px;font-size:12px;color:#c5d5ee}
.tracking-pages button{width:auto;margin:0;min-height:32px;padding:5px 12px;font-size:12px}
@media(max-width:1180px){.tracking-tools{grid-template-columns:repeat(2,minmax(0,1fr))}.tracking-tools input[type=search]{grid-column:1/-1}.tracking-date input{width:100%}}
@media(max-width:860px){.tracking-cards{grid-template-columns:1fr}.tracking-counters{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media(max-width:480px){.tracking-counters{grid-template-columns:repeat(2,minmax(0,1fr))}.tracking-tools{grid-template-columns:1fr}.tracking-card-head{grid-template-columns:auto minmax(0,1fr)}.tracking-card-head .status-label{grid-column:1/-1;justify-self:start}.tracking-actions button{flex:1 1 130px;justify-content:center}}
@media(prefers-reduced-motion:reduce){.tracking-status[data-state=ok]::before,.tracking-card.track-new{animation:none}}
/* Condiciones: gestión documental (versión vigente, borrador, comparación, publicación e historial). */
