.terms-version>div:first-child{display:flex;flex-wrap:wrap;align-items:baseline;gap:4px 10px}
.terms-version strong{font-size:14px;color:#fff}.terms-version em{padding:1px 8px;border-radius:999px;background:#0f2f22;color:#8ff0bd;font-size:11px;font-style:normal;font-weight:600}
.terms-version small,.terms-version .small{font-size:11.5px;color:#9db1cf;margin:0}
.terms-version .receipt-actions{gap:8px}.terms-version .receipt-actions button{width:auto;margin:0;min-height:34px;padding:6px 12px;font-size:12px}
