.tracking-table th:nth-child(1){width:22%}.tracking-table th:nth-child(2){width:15%}.tracking-table th:nth-child(3){width:17%}.tracking-table th:nth-child(4){width:20%}.tracking-table th:nth-child(5){width:11%}.tracking-table th:nth-child(6){width:15%}
