.tracking-sort{display:inline-flex;align-items:center;gap:6px;margin:0;padding:0;border:0;background:none;color:inherit;font:inherit;letter-spacing:inherit;text-transform:inherit;cursor:pointer;min-height:0;width:auto}
.tracking-sort:hover{color:#ffd3e6;transform:none;background:none}.tracking-sort:focus-visible{outline:2px solid #ff9ecb;outline-offset:3px;border-radius:4px}
.tracking-sort svg{width:12px;height:12px;flex:none;color:#ff9ecb;transition:transform .25s ease}.tracking-sort[data-direction=asc] svg{transform:rotate(180deg)}
.tracking-who{display:grid;gap:1px;min-width:0}.tracking-who .tracking-client{display:block}
