/* Teléfono: una tarjeta por orden. Orden y estado arriba; cliente, último movimiento y acciones debajo. */
@media(max-width:860px){
 .tracking-carousel{--track-row:204px}
 .tracking-carousel .tracking-table .tracking-row{grid-template-columns:minmax(0,1fr) auto;gap:6px 10px;padding:10px 12px;align-content:start}
 .tracking-carousel .tracking-table .tracking-row>td:nth-child(5){display:none}
 .tracking-carousel .tracking-table .tracking-row>td:nth-child(2)::before{content:none}
 .tracking-carousel .tracking-row>td:nth-child(2){white-space:normal}
