 .tracking-carousel .tracking-table .tracking-actions .tracking-more-actions span{display:inline}
 .tracking-carousel .tracking-last small{white-space:normal;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}
}
/* Menú de acciones de la fila */
.tracking-menu{position:fixed;z-index:60;display:grid;gap:2px;min-width:210px;max-width:calc(100vw - 16px);padding:6px;border:1px solid #37618d;border-radius:12px;background:#0c192d;box-shadow:0 18px 40px #020714cc,0 0 0 1px #ff9ecb1f}
.tracking-menu button{display:flex;align-items:center;gap:10px;width:100%;min-height:40px;margin:0;padding:8px 12px;border:0;border-radius:8px;background:none;color:#e3eeff;font-size:13px;font-weight:600;text-align:left;cursor:pointer}
.tracking-menu button:hover:not(:disabled),.tracking-menu button:focus-visible{background:#1b3b60;outline:0;transform:none}.tracking-menu button:disabled{opacity:.45;cursor:not-allowed}
.tracking-menu svg{flex:none;width:16px;height:16px;color:#a8dcff}
/* ===== Indicador de progreso técnico: avanza solo con el estado real de la orden ===== */
.tracking-progress{display:flex;align-items:center;gap:6px;width:100%;max-width:168px;min-width:0}
.tracking-table .tracking-progress .tracking-stages{flex:1 1 auto;max-width:none;gap:4px}
.tracking-table .tracking-progress .tracking-stages li{position:relative;height:5px;overflow:hidden;background:#17263f;box-shadow:none;transition:background-color .45s ease,box-shadow .45s ease}
.tracking-table .tracking-progress .tracking-stages li[data-state=done]{background:#3d8fd9;box-shadow:0 0 5px #3d8fd966}
.tracking-table .tracking-progress .tracking-stages li[data-state=current]{background:#5aa9e6;box-shadow:0 0 7px #5aa9e680}
.tracking-table .tracking-progress .tracking-stages li[data-state=unrecorded]{background:repeating-linear-gradient(90deg,#3a4b68 0 4px,#0b1526 4px 7px)}
/* Luz que recorre la etapa actual: tres pasadas al pintarse y otra al pasar el cursor por la fila. No es una animación continua. */
.tracking-table .tracking-progress .tracking-stages li[data-state=current]::after{content:'';display:block;position:absolute;inset:0;width:45%;background:linear-gradient(90deg,transparent,#ffffffd9,transparent);transform:translateX(-120%);animation:tracking-sweep 1.5s ease-in-out 3}
@media(hover:hover){.tracking-row:hover .tracking-progress .tracking-stages li[data-state=current]::after{animation:tracking-sweep-again 1.5s ease-in-out 2}}
@keyframes tracking-sweep{0%{transform:translateX(-120%)}100%{transform:translateX(340%)}}
@keyframes tracking-sweep-again{0%{transform:translateX(-120%)}100%{transform:translateX(340%)}}
/* Listo para entregar: verde suave. Entregado: todas las barras en verde y marca de verificación. */
.tracking-table .tracking-progress:is([data-status=listo],[data-status=espera_entrega]) .tracking-stages li[data-state=current]{background:#3fbf8f;box-shadow:0 0 8px #3fbf8f73}
.tracking-table .tracking-progress:is([data-status=listo],[data-status=espera_entrega]) .tracking-stages li[data-state=done]{background:#2f9d73;box-shadow:0 0 5px #2f9d7359}
