.order-progress-box{display:grid;gap:10px;margin:14px 0 0;padding:14px 16px;border:1px solid #253b5c;border-radius:12px;background:#0c1729}
.order-progress-box .order-progress{margin:0;padding:6px 0 0;border:0;background:none}
.order-progress-head{display:flex;flex-wrap:wrap;align-items:baseline;gap:4px 12px}.order-progress-head:empty{display:none}
.order-progress-head strong{font-size:13px;color:#eef3ff}.order-progress-head span{font-size:12.5px;color:#a9bdd8;overflow-wrap:anywhere}
.order-progress-head em{flex:1 1 100%;font-style:normal;font-size:11.5px;color:#f3d79b}
/* Etapas: completadas en verde, actual en azul, pendientes en gris */
.order-progress li[data-state=done] .progress-label{color:#aef0d2}.order-progress li[data-state=current] .progress-label{color:#fff}
.order-progress li[data-state=current]::before{background:linear-gradient(90deg,#3f9f78,#2868c5)}
.order-overall{display:flex;align-items:center;gap:12px;padding:10px 12px;border:1px solid #3a4f8a;border-radius:11px;background:linear-gradient(160deg,#111d3a,#0c162b)}
.order-overall-icon{display:grid;place-items:center;flex:none;width:34px;height:34px;border-radius:10px;border:1px solid #3a4f8a;color:#c3cffa}.order-overall-icon svg{width:17px;height:17px}
.order-overall>div{display:grid;gap:1px;min-width:0}.order-overall small{font-size:10.5px;letter-spacing:.06em;text-transform:uppercase;color:#8fa0c8}
.order-overall strong{font-size:14.5px;color:#fff}.order-overall span{font-size:12.5px;color:#c7d6ec;overflow-wrap:anywhere}
.order-overall[data-state=completada]{border-color:#2f7d5f;background:linear-gradient(160deg,#12352b,#0b1f1a)}.order-overall[data-state=completada] strong{color:#aef0d2}
.order-overall[data-state=parcial]{border-color:#8a6a2c;background:linear-gradient(160deg,#2a2110,#10182b)}.order-overall[data-state=parcial] strong{color:#ffe2a8}
.order-overall[data-state=listos] strong{color:#9be8dc}
.equip-tab-when{display:block;font-size:11px;color:#8fa6c4}
@media(max-width:520px){.order-progress-box{padding:12px}.order-progress .progress-label{font-size:10px}}
/* ===== «Equipos de esta orden»: resumen de la orden y tarjetas de equipo con jerarquía clara y selección evidente ===== */
.equip-group-head{align-items:center;gap:10px 14px}.equip-group-head h2{flex:0 0 auto}
.equip-summary{display:flex;flex-wrap:wrap;gap:6px;flex:1 1 280px;min-width:0;margin:0;padding:0;list-style:none}
.equip-summary li{padding:3px 10px;border:1px solid #2c4468;border-radius:999px;background:#0c192d;color:#c7d6ec;font-size:12px;font-weight:600;white-space:nowrap}
.equip-summary li[data-kind=code]{font-family:ui-monospace,Menlo,Consolas,monospace;color:#e3eeff;border-color:#37618d}
.equip-summary li[data-kind=entregado]{border-color:#3fbf8f66;background:#12352b;color:#aef0d2}.equip-summary li[data-kind=listo]{border-color:#3fbfb066;background:#0e2a2c;color:#9be8dc}
.equip-summary li[data-kind=proceso]{border-color:#5aa9e666;background:#132c4d;color:#cfe6ff}.equip-summary li[data-kind=recibido]{border-color:#7b879866;background:#1a2436;color:#c3cfe2}
.equip-picker{grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:12px}
.equip-tab.equip-card{position:relative;display:grid;grid-template-rows:auto 1fr auto;gap:0;padding:0;border:1px solid #2c4468;border-radius:14px;background:linear-gradient(180deg,#112540,#0c192d);box-shadow:0 8px 20px -16px #000,inset 0 1px 0 #ffffff0a;overflow:hidden;transition:border-color .2s ease,box-shadow .2s ease,background .2s ease,transform .12s ease}
.equip-tab.equip-card[data-current=true]{border-color:#2c4468;box-shadow:0 8px 20px -16px #000,inset 0 1px 0 #ffffff0a}
.equip-tab .equip-card-top{padding:10px 12px;border-bottom:1px solid #1b2f4d;background:#0d1c33;justify-content:space-between}
.equip-card-id{display:inline-flex;align-items:center;gap:8px;min-width:0}.equip-card-id strong{font:700 14px/1.2 ui-monospace,Menlo,Consolas,monospace;color:#fff;margin:0}
.equip-card-icon{flex:none;width:28px;height:28px}
.equip-card-body{display:grid;gap:3px;padding:10px 12px 8px;min-width:0}
.equip-tab .equip-tab-name{font-size:14.5px;font-weight:700;line-height:1.3;color:#f2f6ff;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;white-space:normal;overflow:hidden;overflow-wrap:anywhere}
.equip-tab-kind{font-size:12px;color:#a9bdd8}.equip-tab .equip-tab-sub{font-size:11.5px;color:#7f93b3;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.equip-card-foot{display:flex;flex-wrap:wrap;align-items:center;gap:4px 8px;min-height:30px;padding:6px 12px 10px}
.equip-tab-when{font-size:11px;color:#7f93b3;margin-right:auto}
.equip-card-picked{display:none;align-items:center;gap:5px;padding:2px 9px;border:1px solid #70b7f5;border-radius:999px;background:#143057;color:#d7ebff;font-size:11px;font-weight:700}
.equip-card-picked svg{width:11px;height:11px;stroke-width:3}
.equip-tab[aria-selected=true] .equip-card-picked{display:inline-flex}
.equip-tab .equip-tab-here{font-style:normal;font-size:11px;color:#f3d79b}
.equip-tab.equip-card[aria-selected=true]{border-color:#70b7f5;background:linear-gradient(180deg,#16335c,#0e2140);box-shadow:0 0 0 2px #70b7f54d,0 14px 28px -18px #70b7f5,inset 0 1px 0 #ffffff14}
.equip-tab.equip-card[aria-selected=true] .equip-card-top{background:#12294a;border-bottom-color:#2f5a92}
.equip-tab.equip-card[aria-selected=true]::after{content:none}
@media(hover:hover){.equip-tab.equip-card:hover{border-color:#5083b8;box-shadow:0 10px 24px -16px #5083b8,inset 0 1px 0 #ffffff0f;transform:none}}
.equip-tab.equip-card:active{transform:scale(.995)}
/* Estados en píldora, uniformes: entregado verde, listo turquesa, en proceso azul, esperas ámbar, recibido gris azulado */
.equip-state{display:inline-flex;align-items:center;gap:6px;padding:3px 10px;line-height:1.3;font-size:11.5px;font-weight:650}
.equip-state::before{content:'';width:6px;height:6px;border-radius:50%;background:currentColor;flex:none}
.equip-state[data-status=pendiente]{border-color:#7b879880;background:#1a2436;color:#c3cfe2}
.equip-state[data-status=reparacion]{border-color:#5aa9e680;background:#132c4d;color:#cfe6ff}
@media(max-width:640px){.equip-picker{grid-template-columns:1fr}.equip-summary{flex-basis:100%}.equip-tab.equip-card{min-height:0}}
@media(prefers-reduced-motion:reduce){.equip-tab.equip-card{transition:none}.equip-tab.equip-card:active{transform:none}}
.equip-card-body{align-content:start}.equip-tab.equip-card{grid-template-rows:auto auto 1fr;align-content:start}.equip-card-foot{align-self:end}
/* Una regla general daba 14 px de margen a cada «small» y alargaba las tarjetas de equipo */
#module-content .equip-tab.equip-card :is(small,em){margin:0}
/* ADI en el nombre de la reserva pública: botón compacto en la línea de la etiqueta (no cambia la altura del formulario) y panel
   flotante con la propuesta. El nombre solo cambia si el cliente la aplica. */
.name-adi-field{position:relative;min-width:0}
.name-adi-chip{position:absolute;top:-4px;right:0;display:inline-flex;align-items:center;gap:5px;height:26px;min-height:0;margin:0;padding:0 10px 0 8px;border:1px solid #ff9ecb59;border-radius:999px;background:#17203f;color:#e3eeff;font:inherit;font-size:11.5px;font-weight:700;letter-spacing:.03em;line-height:1;cursor:pointer;box-shadow:none;transition:background-color .17s ease,border-color .17s ease,box-shadow .17s ease}
.name-adi-chip svg{flex:none;width:14px;height:14px;color:#ff9ecb}
@media(hover:hover){.name-adi-chip:hover{border-color:#ff9ecb;background:#1d2850}}
.name-adi-chip:focus-visible{outline:2px solid #9cc4ff;outline-offset:2px}
.name-adi-chip[data-state=working]{cursor:progress;border-color:#ff9ecb;box-shadow:0 0 0 3px #ff9ecb1f}.name-adi-chip[data-state=working] svg{animation:name-adi-pulse .9s ease-in-out infinite}
.name-adi-chip[data-state=done] svg{animation:name-adi-spark .7s ease-out 1}
body[data-page=appointments] input.adi-glow{border-color:#ff9ecb;box-shadow:0 0 0 3px #ff9ecb26,0 0 18px #ff9ecb33;transition:box-shadow .3s ease,border-color .3s ease}
.name-adi-panel{position:absolute;z-index:30;left:0;right:0;top:calc(100% - 10px);display:grid;gap:8px;padding:13px 14px;border:1px solid #ff9ecb66;border-radius:13px;background:#101b33;box-shadow:0 14px 34px #000a,0 0 0 1px #0006;color:#dbe8fb;font-size:12.5px;font-weight:400;line-height:1.45;animation:name-adi-in .18s ease-out}
.name-adi-panel[hidden]{display:none}
.name-adi-panel-title{display:flex;align-items:center;gap:7px;font-size:13px;font-weight:700;color:#fff}.name-adi-panel-title svg{flex:none;width:15px;height:15px;color:#ff9ecb}
.name-adi-panel p,.name-adi-panel small{margin:0}.name-adi-panel small{font-size:11.5px;color:#9db1cf}
.name-adi-panel-compare{display:grid;gap:6px;margin:0}.name-adi-panel-compare div{display:grid;grid-template-columns:82px minmax(0,1fr);gap:8px;align-items:baseline;padding:7px 10px;border:1px solid #2c4468;border-radius:9px;background:#0c1629}
.name-adi-panel-compare dt{font-size:11px;font-weight:700;letter-spacing:.04em;text-transform:uppercase;color:#8fa6c4}.name-adi-panel-compare dd{margin:0;font-size:13.5px;font-weight:600;overflow-wrap:anywhere;color:#c2d3ec}
.name-adi-panel-compare div[data-kind=old] dd{white-space:pre-wrap}.name-adi-panel-compare div[data-kind=new]{border-color:#ff9ecb73;background:#1a1a36}.name-adi-panel-compare div[data-kind=new] dd{color:#fff}
.name-adi-panel-actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:2px}
.name-adi-panel-actions button{flex:1 1 150px;min-height:40px;margin:0;padding:0 14px;border-radius:10px;font:inherit;font-size:13px;font-weight:650;cursor:pointer;transition:background-color .17s ease,border-color .17s ease}
.name-adi-panel-apply{border:1px solid #3f7fe0;background:linear-gradient(180deg,#2c66bf,#22519c);color:#fff}.name-adi-panel-keep{border:1px solid #2c4468;background:#0c192d;color:#dbe8fb}
@media(hover:hover){.name-adi-panel-apply:hover{background:linear-gradient(180deg,#3472d0,#2859a9)}.name-adi-panel-keep:hover{border-color:#4a6c9c;background:#13233d}}
.name-adi-panel-actions button:focus-visible{outline:2px solid #9cc4ff;outline-offset:2px}
@keyframes name-adi-pulse{50%{opacity:.45;transform:scale(.86)}}
@keyframes name-adi-spark{0%{transform:scale(.6) rotate(-25deg)}55%{transform:scale(1.35) rotate(12deg);filter:drop-shadow(0 0 5px #ff9ecb)}100%{transform:none}}
@keyframes name-adi-in{from{opacity:0;transform:translateY(-4px)}}
@media(prefers-reduced-motion:reduce){.name-adi-chip,.name-adi-chip svg,.name-adi-panel,body[data-page=appointments] input.adi-glow,.name-adi-panel-actions button{animation:none!important;transition:none}}
/* ===== Ventana de ADI: distribución interna, márgenes y alineación. Solo diseño: mismas funciones, enlaces, esfera y colores. ===== */
#adi-widget.adi-v2 .adi-panel,#adi-widget.adi-v2 .adi-panel *{box-sizing:border-box}
/* El relleno genérico de «.adi-panel» (pensado para el asistente de redacción) descuadraba los márgenes de esta ventana. */
#adi-widget.adi-v2 .adi-panel{overflow:hidden;padding:0}
#adi-widget.adi-v2 .adi-panel>header{gap:6px;padding:12px 14px;align-items:center}
#adi-widget.adi-v2 .adi-panel>header>div:not(.adi-menu){min-width:0}
#adi-widget.adi-v2 .adi-panel>header>button{flex:0 0 32px;width:32px;min-width:32px;height:32px;min-height:32px;margin:0;border-radius:9px}
#adi-widget.adi-v2 .adi-messages{flex:1 1 auto;min-height:88px;padding:14px;overflow-x:hidden;overflow-wrap:anywhere}
/* Accesos rápidos: dos columnas y dos filas, botones iguales con el texto centrado y 8 px de separación. */
#adi-widget.adi-v2 .adi-quick,body[data-page=login] #adi-widget.adi-docked .adi-quick{flex:0 0 auto;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;padding:10px 14px 0;overflow:visible}
#adi-widget.adi-v2 .adi-quick[hidden]{display:none}
#adi-widget.adi-v2 .adi-quick button{display:flex;align-items:center;justify-content:center;width:100%;min-width:0;min-height:36px;margin:0;padding:6px 10px;border-radius:10px;font-size:12.5px;line-height:1.2;text-align:center;white-space:normal;overflow-wrap:anywhere}
#adi-widget.adi-v2 .adi-quick button:focus-visible{outline:2px solid #ffb3d4;outline-offset:2px}
/* Campo de mensaje, micrófono y Enviar: misma altura y alineados por la base cuando el texto crece. */
#adi-widget.adi-v2 .adi-panel form#adi-form{align-items:flex-end;gap:8px;padding:10px 14px}
#adi-widget.adi-v2 #adi-form textarea{flex:1 1 auto;min-width:0;min-height:44px;margin:0}
#adi-widget.adi-v2 #adi-form .adi-mic,#adi-widget.adi-v2 #adi-form .adi-stop{flex:0 0 44px;width:44px;height:44px;margin:0}
#adi-widget.adi-v2 #adi-form button[type=submit]{flex:0 0 44px;width:44px;height:44px;margin:0}
/* Accesos inferiores en dos columnas equilibradas (una sola si solo hay un acceso visible). */
#adi-widget.adi-v2 .adi-foot{flex:0 0 auto;display:grid;grid-template-columns:repeat(auto-fit,minmax(104px,1fr));gap:8px;padding:0 14px 12px}
#adi-widget.adi-v2 .adi-foot>*,#adi-widget.adi-v2 .adi-foot .adi-human{display:flex;align-items:center;justify-content:center;width:100%;min-width:0;min-height:36px;margin:0;padding:6px 8px;border:1px solid #24344f;border-radius:10px;background:#0d192c;font-size:12px;line-height:1.2;text-align:center;text-decoration:none;overflow-wrap:anywhere}
#adi-widget.adi-v2 .adi-foot>[hidden]{display:none}
@media(hover:hover){#adi-widget.adi-v2 .adi-foot>*:hover:not(:disabled){border-color:#ff9ecb80;background:#12233d;text-decoration:none}}
#adi-widget.adi-v2 .adi-foot>*:focus-visible{outline:2px solid #ffb3d4;outline-offset:2px}
/* Pantallas pequeñas: la ventana usa el ancho disponible y solo se desplaza el área de mensajes. */
@media(max-width:480px){#adi-widget.adi-v2 .adi-panel{width:calc(100vw - 24px);max-width:calc(100vw - 24px)}}
@media(max-height:560px){#adi-widget.adi-v2 .adi-panel,body[data-page=dashboard] #adi-widget.adi-v2 .adi-panel{max-height:calc(100dvh - 80px)}#adi-widget.adi-v2 .adi-panel>header{padding-top:8px;padding-bottom:8px}}
@media(max-height:620px){#adi-widget.adi-v2 .adi-quick{gap:6px;padding-top:8px}#adi-widget.adi-v2 .adi-quick button,#adi-widget.adi-v2 .adi-foot>*,#adi-widget.adi-v2 .adi-foot .adi-human{min-height:32px}#adi-widget.adi-v2 .adi-messages{min-height:64px}}
#adi-widget.adi-v2 #adi-input::placeholder{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
@media(max-width:360px){#adi-widget.adi-v2 .adi-panel>header strong{font-size:12.5px}#adi-widget.adi-v2 .adi-panel>header{gap:4px;padding-left:12px;padding-right:12px}#adi-widget.adi-v2 .adi-panel>header .adi-avatar{flex-basis:34px;width:34px;height:34px}}
/* ===== Tarjeta financiera (saldo real de la orden o del equipo). Colores por estado; el importe nunca se desborda. ===== */
.finance-card{--fin-bg:#131d33;--fin-line:#33466b;--fin-ink:#c9d6ee;--fin-soft:#9db1cf;display:grid;gap:6px;min-width:0;margin:0;padding:16px;border:1px solid var(--fin-line);border-radius:14px;background:var(--fin-bg);box-shadow:inset 0 1px 0 #ffffff0a;transition:background-color .25s ease,border-color .25s ease}
.finance-card[data-state=pendiente]{--fin-bg:#291927;--fin-line:#86435A;--fin-ink:#FF687B;--fin-soft:#e9b7c2}
.finance-card[data-state=parcial]{--fin-bg:#282319;--fin-line:#80663D;--fin-ink:#FFCA77;--fin-soft:#e3cfa6}
.finance-card[data-state=pagado]{--fin-bg:#142C2A;--fin-line:#356B5C;--fin-ink:#6DE4AF;--fin-soft:#a9d9c6}
.finance-card[data-state=credito]{--fin-bg:#13263a;--fin-line:#3a6f9c;--fin-ink:#7cc7ff;--fin-soft:#a9cbe6}
.finance-card[data-state=unavailable]{--fin-bg:#1c1f2b;--fin-line:#4b5266;--fin-ink:#c3cada;--fin-soft:#a3adc2;border-style:dashed}
.finance-card-head{display:flex;align-items:center;gap:10px;min-width:0}
.finance-card-icon{flex:none;display:grid;place-items:center;width:34px;height:34px;border:1px solid var(--fin-line);border-radius:10px;background:#00000026;color:var(--fin-ink)}.finance-card-icon svg{width:18px;height:18px}
.finance-card-head>div{display:grid;gap:1px;min-width:0}
.finance-card h3{margin:0;font-size:12px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:#e3ecfb}
.finance-card .finance-card-scope{margin:0;font-size:12px;line-height:1.35;color:var(--fin-soft);overflow-wrap:anywhere}
.finance-card-amount{display:block;min-width:0;margin-top:2px;font-size:clamp(24px,7cqi,34px);font-weight:750;line-height:1.1;letter-spacing:-.01em;font-variant-numeric:tabular-nums;color:var(--fin-ink);overflow-wrap:anywhere}
.finance-card{container-type:inline-size}
.finance-card p{margin:0}.finance-card-state{font-size:13.5px;font-weight:650;color:var(--fin-ink)}
.finance-card-extra{font-size:12.5px;line-height:1.45;color:var(--fin-soft)}.finance-card-extra[hidden]{display:none}
.finance-card[data-state=loading] .finance-card-icon svg{animation:draft-spin .9s linear infinite}.finance-card[data-state=loading] .finance-card-amount{opacity:.5}
.finance-breakdown{list-style:none;display:grid;gap:6px;margin:6px 0 0;padding:10px 0 0;border-top:1px solid #ffffff14}
.finance-breakdown li{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:1px 12px;align-items:baseline;min-width:0}
.finance-breakdown li span{font-size:12.5px;font-weight:600;color:#dbe6f8;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.finance-breakdown li small{grid-column:1;margin:0;font-size:11.5px;color:#9db1cf}
.finance-breakdown li b{grid-column:2;grid-row:1/3;align-self:center;font-size:13.5px;font-variant-numeric:tabular-nums;color:#fff;white-space:nowrap}
.finance-breakdown li[data-state=pendiente] small{color:#ff9aa8}.finance-breakdown li[data-state=parcial] small{color:#ffd492}.finance-breakdown li[data-state=pagado] small{color:#8fe8c0}.finance-breakdown li[data-state=credito] small{color:#9bd3ff}
.equip-totals-wrap .equip-totals{grid-template-columns:repeat(3,minmax(0,1fr))}
.equip-pay .finance-card{margin-top:4px}
.equip-pay-sub{margin:16px 0 0;font-size:12px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:#a9bdd8}
.equip-pay-acts{flex:none;display:flex;flex-wrap:wrap;justify-content:flex-end;gap:2px 10px}
.equip-pay-list li[data-kind=devolucion] strong{color:#9bd3ff}.equip-pay-list li[data-kind=asignacion] strong{color:#b4f0d6}
.equip-pay-form select[name=scope]{grid-column:1/-1}.equip-pay-form select[hidden]{display:none}
.equip-pay-refund{display:inline-flex;align-items:center;gap:8px;margin-top:10px}.equip-pay-refund svg{width:15px;height:15px}
@media(max-width:560px){.equip-totals-wrap .equip-totals{grid-template-columns:1fr 1fr}.equip-totals-wrap .equip-totals>div:last-child{grid-column:1/-1}.finance-card{padding:14px}}
@media(prefers-reduced-motion:reduce){.finance-card{transition:none}.finance-card[data-state=loading] .finance-card-icon svg{animation:none}}
/* ===== Verificación en dos pasos: ventana del acceso y bloque de Configuración → Seguridad ===== */
.second-step-dialog{width:min(400px,calc(100% - 32px));margin:auto;padding:24px 22px 18px;border:1px solid #3a5a86a8;border-radius:18px;background:#0d1a2e;color:#e6eeff;box-shadow:0 24px 60px #020714cc}
.second-step-dialog::backdrop{background:#02071499;-webkit-backdrop-filter:blur(3px);backdrop-filter:blur(3px)}
.second-step-dialog form{display:grid;gap:12px;margin:0}
.second-step-dialog h2{margin:0;font-size:18px;color:#fff}.second-step-dialog p{margin:0;font-size:13.5px;line-height:1.5;color:#b9c9e2}
.second-step-dialog label{display:grid;gap:6px;font-size:12.5px;font-weight:600;color:#c2d3ec}
