.mail-sign-card .mail-sign-right p{display:flex;align-items:flex-start;gap:7px;margin:0;padding:3px 0;font-size:13px;line-height:18px;color:#1f2937}
.mail-sign-card .mail-sign-right p span{white-space:nowrap!important;overflow-wrap:normal}.mail-sign-card .mail-sign-right i{flex:0 0 15px;font-size:12px;font-style:normal;color:#e03a3e}
