.stability-badge{--st:#7d8ba1;position:relative;box-sizing:border-box;display:inline-flex;align-items:center;gap:6px;max-width:100%;height:28px;margin:0;padding:0 11px 0 9px;border:1px solid color-mix(in srgb,var(--st) 45%,#21385a);border-radius:999px;background:linear-gradient(180deg,color-mix(in srgb,var(--st) 16%,#0f1d33cc),#0a1424cc);-webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px);box-shadow:inset 0 1px #ffffff14,0 0 12px color-mix(in srgb,var(--st) 18%,transparent);color:#e6eefc;font-size:11.5px;font-weight:600;line-height:1;letter-spacing:.02em;white-space:nowrap;cursor:pointer;transition:border-color .2s,box-shadow .2s}
.stability-badge:hover{border-color:color-mix(in srgb,var(--st) 75%,#21385a);box-shadow:inset 0 1px #ffffff1f,0 0 16px color-mix(in srgb,var(--st) 32%,transparent)}
.stability-badge:focus-visible{outline:2px solid #8bb8ff;outline-offset:2px}
.stability-badge svg{flex:none;width:14px;height:14px;fill:none;stroke:var(--st);stroke-width:2.2;stroke-linecap:round;stroke-linejoin:round}
.stability-badge .stability-version{font-variant-numeric:tabular-nums}
.stability-badge .stability-sep{color:#6f84a3}
.stability-badge .stability-label{color:var(--st);font-weight:800;letter-spacing:.06em;overflow:hidden;text-overflow:ellipsis}
.stability-badge[data-state=stable],.stability-state[data-state=stable]{--st:#3fd39a}
.stability-badge[data-state=verifying],.stability-state[data-state=verifying]{--st:#5aa9ff}
.stability-badge[data-state=observing],.stability-state[data-state=observing]{--st:#ffb455}
.stability-badge[data-state=attention],.stability-state[data-state=attention]{--st:#ff6b78}
.stability-badge[data-state=unverified],.stability-state[data-state=unverified]{--st:#9aa8bd}
.stability-badge[data-state=verifying] svg{animation:stability-spin 1.4s linear infinite}
@keyframes stability-spin{to{transform:rotate(360deg)}}
.stability-dialog{width:min(440px,calc(100% - 24px));max-height:calc(100dvh - 32px);padding:16px 18px;border:1px solid #27406a;border-radius:16px;background:linear-gradient(180deg,#0f1d33,#0a1424);color:#dbe8fb;box-shadow:0 24px 60px #000a,0 0 0 1px #4087ef14;overflow-y:auto}
.stability-dialog::backdrop{background:#030812b3;-webkit-backdrop-filter:blur(3px);backdrop-filter:blur(3px)}
.stability-dialog header{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:10px}
.stability-dialog h2{margin:0;font-size:16px;color:#f2f6ff}
.stability-dialog h3{margin:12px 0 6px;font-size:11px;letter-spacing:.07em;text-transform:uppercase;color:#8198ba}
.stability-close{display:grid;place-items:center;width:30px;height:30px;min-height:0;margin:0;padding:0;border:1px solid #2a4063;border-radius:8px;background:#10203a;color:#c5d5ee;font-size:18px;line-height:1;cursor:pointer}
.stability-close:focus-visible{outline:2px solid #8bb8ff;outline-offset:2px}
.stability-state{--st:#9aa8bd;display:grid;grid-template-columns:auto 1fr;gap:2px 8px;align-items:center;margin:0 0 10px;padding:10px 12px;border:1px solid color-mix(in srgb,var(--st) 40%,#1f3352);border-radius:12px;background:color-mix(in srgb,var(--st) 9%,#0b1628)}
.stability-state svg{grid-row:span 2;width:20px;height:20px;fill:none;stroke:var(--st);stroke-width:2.2;stroke-linecap:round;stroke-linejoin:round}
.stability-state strong{color:var(--st);font-size:14px}.stability-state span{font-size:12px;line-height:1.45;color:#b9c9e2}
.stability-facts{display:grid;gap:5px;margin:0}
.stability-facts div{display:grid;grid-template-columns:170px minmax(0,1fr);gap:8px;font-size:12.5px}
.stability-facts dt{color:#8198ba}.stability-facts dd{margin:0;color:#e6eefc;overflow-wrap:anywhere}
.stability-tests{list-style:none;margin:0;padding:0;display:grid;gap:4px}
.stability-tests li{display:flex;align-items:center;gap:7px;font-size:12.5px}
.stability-tests svg{flex:none;width:14px;height:14px;fill:none;stroke-width:2.6;stroke-linecap:round;stroke-linejoin:round}
.stability-tests li[data-ok=true] svg{stroke:#3fd39a}.stability-tests li[data-ok=false] svg{stroke:#ff6b78}.stability-tests li[data-ok=false]{color:#ffc2c7}
.stability-incidents p{margin:0 0 4px;font-size:12px;color:#b9c9e2}.stability-incidents p[data-critical=true]{color:#ff9aa3}
.stability-rule{margin:12px 0 0;padding-top:10px;border-top:1px solid #1c2c47;font-size:11.5px;line-height:1.5;color:#8fa5c4}
#stability-top{flex:none}
.stability-badge .stability-label{overflow:visible;text-overflow:clip}
#stability-login{padding-left:50px}
@media(max-width:1440px){#stability-top .stability-badge .stability-version,#stability-top .stability-badge .stability-sep{display:none}}
/* Con poco ancho la barra superior conserva solo el icono de estado (nombre accesible, descripción y la misma ventana de detalle). */
@media(max-width:1280px){#stability-top .stability-badge{width:32px;height:32px;padding:0;justify-content:center}#stability-top .stability-badge>span{display:none}#stability-top .stability-badge svg{width:16px;height:16px}}
/* Celulares: el distintivo completo pasa al menú de navegación; en la barra superior no hay espacio junto al título. */
.stability-nav{display:none}
@media(max-width:860px){#stability-top{display:none}.stability-nav{display:flex;padding:10px 12px 4px}}
@media(max-width:420px){#stability-login{padding-left:0}}
@media(max-width:480px){.stability-facts div{grid-template-columns:1fr;gap:0}}
@media(prefers-reduced-motion:reduce){.stability-badge,.stability-badge[data-state=verifying] svg{transition:none;animation:none}}
/* El distintivo conserva su tipografía dentro del menú de navegación (que agranda los textos de sus enlaces). */
.stability-slot .stability-badge>span{font-size:11.5px;line-height:1;font-weight:600;letter-spacing:.02em;color:#e6eefc}
.stability-slot .stability-badge>.stability-label{font-weight:800;letter-spacing:.06em;color:var(--st)}
.stability-slot .stability-badge>.stability-sep{color:#6f84a3}
.stability-slot .stability-badge{width:auto;min-width:0;max-width:100%;flex:none}
.stability-nav{grid-column:1/-1}
@media(max-width:1280px){#stability-top .stability-badge{width:32px}}
.stability-previous{list-style:none;margin:0;padding:0;display:grid;gap:3px;font-size:12px;color:#b9c9e2}
.stability-badge[data-state=stable]{box-shadow:inset 0 1px #ffffff1f,0 0 14px #3fd39a40}
/* Monitor de estabilidad: colores de estado — estable verde, en observación ámbar, incidencia rojo, pendiente o verificando azul. */
.stability-badge[data-state=unverified],.stability-state[data-state=unverified],.stability-dialog[data-state=unverified]{--st:#5aa9ff}
.stability-badge[data-state=verifying],.stability-state[data-state=verifying],.stability-dialog[data-state=verifying]{--st:#5aa9ff}
.stability-dialog[data-state=observing]{--st:#ffb455}.stability-dialog[data-state=stable]{--st:#3fd39a}.stability-dialog[data-state=attention]{--st:#ff6b78}
/* Indicador unificado de la barra superior: versión + luz de estado + estado real de estabilidad, en un solo componente. */
.premium-header .release-chip{gap:8px;height:34px;padding:0 12px 0 10px;border:1px solid #243a5c;background:linear-gradient(180deg,#0f1f38,#0b1629);box-shadow:inset 0 1px #ffffff0d;font-family:inherit}
.release-chip .release-label{font-size:12px;font-weight:700;letter-spacing:.02em;font-variant-numeric:tabular-nums;color:#e6eefc;font-family:inherit}
.release-chip .release-dot{display:none}
.release-stability{--st:#5aa9ff;display:inline-flex;align-items:center;gap:6px;padding-left:9px;border-left:1px solid #26405f;font-size:10.5px;font-weight:800;letter-spacing:.07em;text-transform:uppercase;color:var(--st);white-space:nowrap}
.release-stability[data-state=stable]{--st:#3fd39a}.release-stability[data-state=observing]{--st:#ffb455}.release-stability[data-state=attention],.release-stability[data-state=error]{--st:#ff6b78}
.release-light{position:relative;flex:none;width:7px;height:7px;border-radius:50%;background:var(--st);box-shadow:0 0 0 2px color-mix(in srgb,var(--st) 22%,transparent),0 0 8px color-mix(in srgb,var(--st) 70%,transparent)}
.release-stability:is([data-state=observing],[data-state=verifying],[data-state=pending]) .release-light::after{content:'';position:absolute;inset:-4px;border-radius:50%;border:1px solid var(--st);opacity:0;animation:release-light 2.6s ease-out infinite}
@keyframes release-light{0%{transform:scale(.6);opacity:.55}100%{transform:scale(1.6);opacity:0}}
.premium-header .release-chip:hover{border-color:#3b5f92}
@media(max-width:1280px) and (min-width:1000px){.release-stability{font-size:0;gap:0;padding-left:8px}.release-stability .release-stability-text{display:none}}
@media(max-width:999px){.release-chip{align-self:flex-start}}
/* Ventana «Estabilidad de la versión»: compacta, con luz de estado, cuenta atrás, barra del período y verificaciones. */
.stability-dialog{--st:#5aa9ff;width:min(420px,calc(100% - 24px));padding:14px 16px 12px}
.stability-head{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:10px;margin-bottom:10px}
.stability-head h2{margin:0;font-size:15px}
.stability-sub{margin:1px 0 0;font-size:11.5px;color:#8fa5c4;font-variant-numeric:tabular-nums}
.stability-light{width:10px;height:10px;border-radius:50%;background:var(--st);box-shadow:0 0 0 3px color-mix(in srgb,var(--st) 20%,transparent),0 0 12px color-mix(in srgb,var(--st) 65%,transparent)}
.stability-dialog:is([data-state=observing],[data-state=verifying]) .stability-light{animation:stability-breathe 2.8s ease-in-out infinite}
@keyframes stability-breathe{50%{box-shadow:0 0 0 5px color-mix(in srgb,var(--st) 10%,transparent),0 0 16px color-mix(in srgb,var(--st) 45%,transparent)}}
.stability-dialog .stability-state{padding:8px 10px;margin-bottom:10px}
.stability-dialog .stability-state strong{font-size:13px}.stability-dialog .stability-state span{font-size:11.5px}
.stability-period{display:grid;gap:7px;padding:11px 12px;margin-bottom:10px;border:1px solid #1f3352;border-radius:12px;background:#0a1424}
.stability-clock{display:flex;align-items:baseline;flex-wrap:wrap;gap:4px 8px}
.stability-count{font-size:22px;line-height:1.1;font-weight:800;color:#f2f6ff;font-variant-numeric:tabular-nums}
.stability-count-label{font-size:11.5px;color:#8fa5c4}
.stability-bar{position:relative;height:6px;border-radius:999px;background:#16263f;overflow:hidden}
.stability-bar i{position:absolute;inset:0 auto 0 0;width:0;border-radius:inherit;background:linear-gradient(90deg,color-mix(in srgb,var(--st) 60%,#0a1424),var(--st));box-shadow:0 0 8px color-mix(in srgb,var(--st) 55%,transparent);transition:width .6s ease}
.stability-span{display:flex;justify-content:space-between;gap:8px;font-size:10.5px;color:#7f93b2;font-variant-numeric:tabular-nums}
.stability-checks{display:flex;align-items:center;gap:9px;font-size:12px;color:#c5d5ee}
.stability-dots{display:flex;gap:4px}
.stability-dots i{width:18px;height:6px;border-radius:999px;background:#1d2f4c;border:1px solid #2a4063}
.stability-dots i[data-done=true]{background:var(--st);border-color:transparent;box-shadow:0 0 6px color-mix(in srgb,var(--st) 55%,transparent)}
.stability-dialog .stability-facts{grid-template-columns:1fr 1fr;gap:8px 12px;margin-bottom:8px}
.stability-dialog .stability-facts div{display:grid;grid-template-columns:1fr;gap:1px}
.stability-dialog .stability-facts dt{font-size:10.5px;letter-spacing:.04em;text-transform:uppercase}
.stability-dialog .stability-facts dd{font-size:12.5px;font-variant-numeric:tabular-nums}
.stability-note{margin:0 0 8px;padding:7px 10px;border-left:3px solid #ffb455;border-radius:6px;background:#1d1a14;font-size:11.5px;color:#f3dcb0}
.stability-block{border-top:1px solid #1c2c47}
.stability-block summary{display:flex;align-items:center;justify-content:space-between;padding:8px 2px;font-size:12px;font-weight:700;color:#c5d5ee;cursor:pointer;list-style:none}
.stability-block summary::-webkit-details-marker{display:none}
.stability-block summary::after{content:'';width:7px;height:7px;border-right:2px solid #6f84a3;border-bottom:2px solid #6f84a3;transform:rotate(45deg);transition:transform .2s}
.stability-block[open] summary::after{transform:rotate(-135deg)}
.stability-block summary:focus-visible{outline:2px solid #8bb8ff;outline-offset:2px;border-radius:6px}
.stability-block>:not(summary){margin-bottom:8px}
.stability-empty,.stability-incident{margin:0 0 4px;font-size:12px;color:#b9c9e2}.stability-incident[data-critical=true]{color:#ff9aa3}
.stability-previous li{display:flex;flex-wrap:wrap;gap:4px 8px}.stability-previous strong{color:#e6eefc}
.stability-updates{border-top:1px solid #1c2c47;padding-top:8px}
.stability-updates-open{display:inline-flex;align-items:center;gap:7px;width:auto;min-height:32px;margin:0;padding:0 11px;border:1px solid #2a4063;border-radius:9px;background:#10203a;color:#c5d5ee;font-size:12px;font-weight:650;cursor:pointer}
.stability-updates-open svg{width:14px;height:14px;fill:none;stroke:#8bb8ff;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.stability-updates-open:focus-visible{outline:2px solid #8bb8ff;outline-offset:2px}
.stability-dialog .stability-rule{margin-top:8px;font-size:10.5px}
@media(max-width:420px){.stability-dialog .stability-facts{grid-template-columns:1fr}.stability-count{font-size:20px}}
/* Buscador de la barra: atajo «/» visible en escritorio mientras el campo está vacío y sin foco. */
.premium-header #global-search{position:relative}
.premium-header #global-search .search-kbd{flex:none;display:inline-grid;place-items:center;min-width:18px;height:18px;padding:0 4px;border:1px solid #2c405c;border-radius:5px;background:#0b1626;color:#7f93b2;font:600 10.5px/1 ui-monospace,monospace}
.premium-header #global-search:focus-within .search-kbd,.premium-header #global-search:has(input:not(:placeholder-shown)) .search-kbd{display:none}
@media(hover:none),(max-width:999px){.premium-header #global-search .search-kbd{display:none}}
@media(prefers-reduced-motion:reduce){.release-stability .release-light::after,.stability-dialog .stability-light{animation:none}.stability-bar i,.stability-block summary::after{transition:none}}
.stability-head>div{min-width:0;text-align:left}.stability-head h2,.stability-head .stability-sub{text-align:left}
/* ADI AutoCare Pro (módulo Sistema): panel compacto con estado general, servicios, incidencias, historial, versiones y avisos. */
.autocare{--ac:#5aa9ff;display:grid;gap:10px;margin-bottom:16px;padding:14px 16px;border:1px solid #22385a;border-radius:14px;background:linear-gradient(180deg,#0e1b30,#0a1424)}
.autocare[data-general=ok]{--ac:#3fd39a}.autocare[data-general=degraded]{--ac:#ffb455}.autocare[data-general=critical]{--ac:#ff6b78}
.autocare-head{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:12px}
.autocare-head h2{margin:0;font-size:16px;color:#f2f6ff}
.autocare-sub{margin:2px 0 0;font-size:12px;color:#9db1cf}
.autocare-light{width:11px;height:11px;border-radius:50%;background:var(--ac);box-shadow:0 0 0 3px color-mix(in srgb,var(--ac) 22%,transparent),0 0 12px color-mix(in srgb,var(--ac) 60%,transparent)}
.autocare[data-general=degraded] .autocare-light,.autocare[data-general=critical] .autocare-light{animation:stability-breathe 2.6s ease-in-out infinite;--st:var(--ac)}
.autocare-run{display:inline-flex;align-items:center;gap:7px;width:auto;margin:0;min-height:36px;padding:0 14px;font-size:12.5px}
.autocare-run svg{width:15px;height:15px}
.autocare-run[data-busy=true] svg{animation:stability-spin 1.4s linear infinite}
.autocare-stats{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:8px;margin:0}
.autocare-stats div{min-width:0;padding:8px 10px;border:1px solid #1f3352;border-radius:10px;background:#0b1628}
.autocare-stats dt{font-size:10.5px;letter-spacing:.05em;text-transform:uppercase;color:#7f93b2}
.autocare-stats dd{margin:2px 0 0;font-size:12.5px;font-weight:650;color:#e6eefc;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.autocare-block{border-top:1px solid #1c2c47}
.autocare-block summary{padding:9px 2px;font-size:12.5px;font-weight:700;color:#c5d5ee;cursor:pointer}
.autocare-block summary:focus-visible{outline:2px solid #8bb8ff;outline-offset:2px;border-radius:6px}
.autocare-block>:not(summary){margin:0 0 10px}
.autocare-services{list-style:none;padding:0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px}
.autocare-services li{display:grid;grid-template-columns:auto minmax(0,1fr) auto;grid-template-areas:"dot name ms" "dot detail detail";gap:1px 8px;align-items:center;padding:7px 10px;border:1px solid #1c2c47;border-radius:9px;background:#0a1424;font-size:12px}
.autocare-services li i{grid-area:dot;width:8px;height:8px;border-radius:50%;background:#3fd39a;box-shadow:0 0 6px #3fd39a80}
.autocare-services li[data-ok=false] i{background:#ff6b78;box-shadow:0 0 6px #ff6b7880}
.autocare-services li strong{grid-area:name;color:#e6eefc;font-size:12.5px}.autocare-services li span{grid-area:detail;color:#8fa5c4;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.autocare-services li small{grid-area:ms;color:#6f84a3;font-variant-numeric:tabular-nums}
.autocare-list{display:grid;gap:6px}
.autocare-incident{--sv:#ffb455;padding:8px 10px;border:1px solid #1f3352;border-left:3px solid var(--sv);border-radius:9px;background:#0a1424}
.autocare-incident[data-severity=critical]{--sv:#ff6b78}.autocare-incident[data-severity=high]{--sv:#ff8f5a}.autocare-incident[data-severity=low]{--sv:#5aa9ff}
.autocare-incident div{display:flex;flex-wrap:wrap;align-items:baseline;gap:4px 8px}
.autocare-incident b{font-size:10.5px;letter-spacing:.06em;text-transform:uppercase;color:var(--sv)}.autocare-incident strong{font-size:12.5px;color:#e6eefc}.autocare-incident small{font-size:11px;color:#7f93b2}
.autocare-incident p{margin:3px 0 0;font-size:12px;color:#c5d5ee}.autocare-incident code{display:block;margin-top:3px;font-size:11px;color:#8fa5c4;overflow-wrap:anywhere}
.autocare-history,.autocare-versions{list-style:none;padding:0;display:grid;gap:5px}
.autocare-history li,.autocare-versions li{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:8px;align-items:baseline;font-size:12px;color:#c5d5ee}
.autocare-history b{font-size:10.5px;letter-spacing:.05em;text-transform:uppercase;color:#8bb8ff}
.autocare-history li[data-kind=incident] b{color:#ff8794}.autocare-history li[data-kind=recovery] b,.autocare-history li[data-kind=resolved] b{color:#6de4af}
.autocare-history small,.autocare-versions small{color:#7f93b2;white-space:nowrap}.autocare-versions strong{color:#e6eefc}
.autocare-empty,.autocare-note{font-size:12px;color:#8fa5c4}
.autocare-prefs{display:flex;flex-wrap:wrap;align-items:center;gap:8px 16px}
.autocare-prefs label{display:inline-flex;align-items:center;gap:7px;margin:0;font-size:12.5px;color:#c5d5ee}
.autocare-prefs input[type=checkbox]{width:16px;height:16px;min-height:0;margin:0;accent-color:#4d8df0}
.autocare-prefs select{width:auto;min-height:32px;margin:0;font-size:12.5px}
.autocare-prefs button{width:auto;margin:0;min-height:32px;padding:0 12px;font-size:12px}
@media(max-width:1100px){.autocare-stats{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media(max-width:700px){.autocare-head{grid-template-columns:auto minmax(0,1fr)}.autocare-run{grid-column:1/-1;justify-content:center}.autocare-stats{grid-template-columns:repeat(2,minmax(0,1fr))}.autocare-services{grid-template-columns:1fr}.autocare-history li,.autocare-versions li{grid-template-columns:1fr;gap:1px}}
@media(prefers-reduced-motion:reduce){.autocare-light,.autocare-run[data-busy=true] svg{animation:none}}
/* Libreta de direcciones (Mail Pro): ventana compacta con lista desplazable, casillas, selección masiva y contador. */
.contact-picker{width:min(560px,calc(100% - 24px));max-height:calc(100dvh - 32px)}
.contact-picker[open]{display:grid;grid-template-rows:auto minmax(0,1fr) auto}
.picker-body{display:grid;grid-template-rows:auto auto auto minmax(0,1fr);gap:8px;min-height:0;flex:1 1 auto;margin-top:8px}
.picker-stats{margin:0;font-size:11.5px;color:#8fa5c4}
.picker-body input[type=search]{margin:0;min-height:36px;height:36px;font-size:13px}
