.tracking-recur{flex:none;display:inline-flex;align-items:center;height:16px;padding:0 6px;border:1px solid #a86818;border-radius:999px;font-size:10px;font-weight:700;line-height:1;color:#ffb75e;white-space:nowrap}
.recurrence-box{margin:0 0 10px;padding:9px 12px;border:1px solid #6b4512;border-left:3px solid #d08a2e;border-radius:10px;background:#1c1409}
.recurrence-box strong{font-size:12.5px;color:#ffc27a}
.recurrence-box ol{list-style:none;margin:6px 0 0;padding:0;display:grid;gap:5px}
.recurrence-box li{display:grid;gap:1px;font-size:12px;color:#e8d6bd}.recurrence-box b{font-size:11px;color:#ffb75e}.recurrence-box small{font-size:11px;color:#b39b7c}
