.quote-badge[data-status=parcial]{border-color:#5aa9ff80;background:#11254a;color:#b9dcff}
.quote-badge[data-status=sin_correo]{border-color:#e06c7880;background:#3a1a22;color:#ffc4c9}
.budget-head-state .quote-badge[data-status=enviado],.budget-head-state .quote-badge[data-status=revision]{border-color:#e0a24a80;background:#33260f;color:#ffd08a}
.budget-head-state .quote-badge[data-status=parcial]{border-color:#5aa9ff80;background:#11254a;color:#b9dcff}
.budget-head-state .quote-badge[data-status=sin_correo]{border-color:#e06c7880;background:#3a1a22;color:#ffc4c9}
/* Tarjetas de equipos (E01, E02…): cabecera con identificador e icono a la izquierda y estado compacto a la derecha, sin superposición;
   selección con borde azul discreto e indicador pequeño; alturas uniformes por fila. */
.equip-picker{align-items:stretch}
.equip-tab.equip-card{border-color:#24395a;background:linear-gradient(180deg,#0f2038,#0b182b);box-shadow:inset 0 1px 0 #ffffff08;transition:border-color .18s ease,box-shadow .18s ease,background-color .18s ease}
.equip-tab .equip-card-top{display:flex;align-items:center;gap:8px;min-width:0;padding:9px 10px 9px 12px}
.equip-tab .equip-card-id{flex:0 0 auto;gap:7px}
.equip-tab .equip-card-id strong{font-size:13.5px;letter-spacing:.02em}
.equip-tab .equip-card-icon{width:24px;height:24px}
.equip-tab .equip-card-top .equip-state{flex:0 1 auto;min-width:0;max-width:100%;margin-left:auto;box-sizing:border-box;display:inline-flex;align-items:center;height:24px;padding:0 9px;border-radius:999px;font-size:11px;font-weight:700;line-height:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.equip-tab .equip-card-picked{flex:none;display:none;place-items:center;width:20px;height:20px;padding:0;border:1px solid #5aa9ff;border-radius:50%;background:#173a66;color:#d7ebff}
