.equip-tab[aria-selected=true] .equip-card-picked{display:inline-grid}
.equip-tab .equip-card-body{gap:2px;padding:9px 12px 6px}
.equip-tab .equip-tab-name{font-size:14px}
.equip-tab .equip-card-foot{min-height:0;padding:4px 12px 10px}
.equip-tab.equip-card[aria-selected=true]{border-color:#5aa9ff;background:linear-gradient(180deg,#13294a,#0d1d35);box-shadow:0 0 0 1px #5aa9ff40,0 8px 22px -16px #5aa9ff}
.equip-tab.equip-card[aria-selected=true] .equip-card-top{background:#112645;border-bottom-color:#264b7a}
.equip-tab.equip-card:focus-visible{outline:2px solid #8bb8ff;outline-offset:2px}
@media(prefers-reduced-motion:reduce){.equip-tab.equip-card{transition:none}}
/* Verificación en dos pasos: asistente compacto (configurar → verificar), QR centrado, clave manual oculta y campo de 6 dígitos. */
.mfa-wizard{display:grid;gap:12px;max-width:440px;min-width:0}
.mfa-progress{list-style:none;display:grid;grid-template-columns:1fr 1fr;gap:6px;margin:0;padding:0;counter-reset:mfa}
.mfa-progress li{counter-increment:mfa;display:flex;align-items:center;gap:7px;padding:6px 8px;border:1px solid #22385a;border-radius:9px;font-size:11.5px;font-weight:650;color:#8fa5c4;min-width:0}
.mfa-progress li::before{content:counter(mfa);flex:none;display:grid;place-items:center;width:18px;height:18px;border-radius:50%;background:#1b2f4f;font-size:10.5px;color:#c5d5ee}
.mfa-progress li[data-state=current]{border-color:#4d8df0;color:#e6eefc;background:#10233f}.mfa-progress li[data-state=current]::before{background:#2f6fd0;color:#fff}
.mfa-progress li[data-state=done]{color:#8fe0b9}.mfa-progress li[data-state=done]::before{content:'✓';background:#1d5a43;color:#c9f5df}
.mfa-stage{display:grid;gap:10px;justify-items:center;text-align:center;animation:mfa-in .22s ease-out}
@keyframes mfa-in{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:none}}
.mfa-lead{margin:0;font-size:13px;line-height:1.45;color:#c2d3ec}
.mfa-qr{width:172px;padding:8px}
.mfa-apps{margin:0;font-size:11.5px;line-height:1.45;color:#8fa5c4;max-width:360px}
.mfa-key{display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:6px 8px;padding:8px 10px;border:1px solid #1f3352;border-radius:10px;background:#0a1424;max-width:100%}
.mfa-key-label{flex-basis:100%;font-size:11.5px;color:#8fa5c4}
.mfa-key .second-step-key{margin:0;font-size:12.5px;letter-spacing:.04em;overflow-wrap:anywhere}
.mfa-key button{width:auto;margin:0;min-height:30px;padding:0 10px;font-size:12px}
.mfa-stage .config-buttons{justify-content:center}
.mfa-verify{justify-items:center;width:100%}
.mfa-verify .second-step-field{justify-items:center}
.mfa-code{max-width:220px!important;height:48px;text-align:center;font:700 24px/1 ui-monospace,SFMono-Regular,Menlo,Consolas,monospace!important;letter-spacing:.35em;padding-left:.35em!important}
.mfa-status{margin:0;min-height:18px;font-size:12.5px;color:#9db1cf}
.mfa-status[data-state=error]{color:#ffb3b6}.mfa-status[data-state=busy]{color:#8bb8ff}
@media(max-width:480px){.mfa-progress{grid-template-columns:1fr}.mfa-qr{width:160px}}
@media(prefers-reduced-motion:reduce){.mfa-stage{animation:none}}
/* QR de la autenticación en dos pasos: cuadro blanco cuadrado de tamaño fijo y SVG escalable que ocupa todo el cuadro (nunca recortado). */
