.agenda-config-facts{display:flex;flex-wrap:wrap;gap:6px}
.agenda-config-fact{display:inline-flex;align-items:center;gap:6px;min-width:0;padding:3px 10px;border:1px solid #1f3352;border-radius:999px;background:#0a1525;font-size:11.5px;color:#a9bddb}
