body[data-page=dashboard] dialog.agenda-settings{display:grid;grid-template-rows:auto auto minmax(0,1fr) auto;width:min(1080px,calc(100vw - 24px));max-width:none;max-height:90dvh;padding:0;overflow:hidden;border:1px solid #2a4266;border-radius:16px;background:#0b1526}
