dialog.agenda-settings .dialog-heading>button{grid-column:2;grid-row:1/span 2}
.agenda-tabs{display:flex;gap:4px;padding:0 14px;border-bottom:1px solid #1d3150;overflow-x:auto;scrollbar-width:thin}
