.agenda-hours-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(290px,1fr));gap:10px;align-items:start}
.agenda-hours-card{display:grid;gap:6px;padding:10px 12px;border:1px solid #22385a;border-radius:12px;background:linear-gradient(180deg,#0f2038,#0b182b);transition:border-color .18s ease}
