.agenda-switch{position:relative;display:inline-flex;align-items:center;gap:7px;margin:0;cursor:pointer;font-size:11.5px;color:#a9bddb}
.agenda-switch input{position:absolute;opacity:0;width:34px;height:20px;margin:0;cursor:pointer}
.agenda-switch-track{position:relative;flex:none;width:34px;height:20px;border-radius:999px;background:#2a3b55;transition:background-color .18s ease}
.agenda-switch-track::after{content:"";position:absolute;top:3px;left:3px;width:14px;height:14px;border-radius:50%;background:#d6e1f3;transition:transform .18s ease}
.agenda-switch input:checked+.agenda-switch-track{background:#1fa596}.agenda-switch input:checked+.agenda-switch-track::after{transform:translateX(14px)}
