#adi-widget.adi-v2.adi-gl .adi-orb-label{display:none}
#adi-widget.adi-v2:not(.adi-gl) .adi-toggle .adi-orb{background:radial-gradient(circle at 50% 48%,#0b0418 0,#140629 46%,#2a0b4d 60%,transparent 71%),conic-gradient(from 200deg,#2f6bff,#3fc8ff 12%,#6a2cff 26%,#c624e6 44%,#ff2fa6 60%,#ffb0dd 68%,#ff2fa6 76%,#8a2cff 90%,#2f6bff);box-shadow:0 0 16px #ff3fa880,0 0 4px #ffb3dd99,inset 0 0 12px #ff5cc580;filter:none}
#adi-widget.adi-v2:not(.adi-gl) .adi-toggle .adi-orb::before{content:"";position:absolute;inset:4%;border-radius:50%;background:conic-gradient(from 0deg,#ffffff00 0 12%,#ff6fc8b3 22%,#ffffff00 34%,#5b8dffa6 50%,#ffffff00 62%,#d23cf0b3 78%,#ffffff00 90%);-webkit-mask:radial-gradient(circle,transparent 40%,#000 62%,transparent 76%);mask:radial-gradient(circle,transparent 40%,#000 62%,transparent 76%);filter:blur(1.5px);mix-blend-mode:screen;opacity:.9;animation:adi-fil-spin 12s linear infinite}
#adi-widget.adi-v2:not(.adi-gl) .adi-toggle .adi-orb::after{display:none}
#adi-widget.adi-v2:not(.adi-gl) :is(.adi-orb-shine,.adi-orb-swirl){display:none}
#adi-widget.adi-v2:not(.adi-gl) .adi-orb-label{color:#fff;text-shadow:0 0 8px #ff3fa8,0 1px 2px #000}
#adi-widget.adi-v2:not(.adi-gl).adi-busy .adi-toggle .adi-orb::before{animation-duration:4s}
@keyframes adi-fil-spin{to{transform:rotate(360deg)}}
@media(prefers-reduced-motion:reduce){#adi-widget.adi-v2:not(.adi-gl) .adi-toggle .adi-orb::before{animation:none}}
.lcat-skeleton{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:12px;margin-top:12px}
.lcat-skeleton span{height:210px;border:1px solid #1f3352;border-radius:12px;background:linear-gradient(100deg,#0c182b 30%,#13243d 50%,#0c182b 70%);background-size:300% 100%;animation:lcat-skeleton 1.4s ease infinite}
@keyframes lcat-skeleton{from{background-position:100% 0}to{background-position:0 0}}
@media(prefers-reduced-motion:reduce){.lcat-skeleton span{animation:none}}
